UPDATE branches b SET latitude = gps.latitude, longitude = gps.longitude
FROM gps WHERE b."dealerId" = gps."dealerId" AND b."isHeadOffice" = true
AND (b.latitude IS NULL OR b.longitude IS NULL);

UPDATE vehicles v SET latitude = b.latitude, longitude = b.longitude
FROM branches b WHERE v."branchId" = b.id
AND v."sourceData"->>'vehicle_id' IS NOT NULL
AND (v.latitude IS NULL OR v.longitude IS NULL)
AND b.latitude BETWEEN -35.5 AND -22 AND b.longitude BETWEEN 16 AND 33.5;
